//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

pub type PlayerId = u32;

#[derive(Default)]
struct State {
    scores: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
///
/// One lock guards scores and total together: every operation is atomic (no
/// lost updates from read-then-write) and there is no lock ordering to
/// deadlock on (transfer used to lock two slots in caller order).
#[derive(Clone, Default)]
pub struct Board {
    state: Arc<Mutex<State>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    fn lock(&self) -> MutexGuard<'_, State> {
        // Every mutation validates before writing, so state is consistent even
        // if another thread panicked while holding the lock.
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }

    fn missing(id: PlayerId) -> ! {
        panic!("unknown player id {id}: expected an id passed to join()")
    }

    /// Joining an existing id replaces its score; the total stays the sum of scores.
    pub fn join(&self, id: PlayerId, score: i64) {
        let mut s = self.lock();
        let old = s.scores.insert(id, score).unwrap_or(0);
        s.total += score - old;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut s = self.lock();
        match s.scores.get_mut(&id) {
            Some(v) => *v += points,
            None => Self::missing(id),
        }
        s.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut s = self.lock();
        for id in [from, to] {
            if !s.scores.contains_key(&id) {
                Self::missing(id);
            }
        }
        if from == to {
            return;
        }
        *s.scores.get_mut(&from).unwrap() -= points;
        *s.scores.get_mut(&to).unwrap() += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        match self.lock().scores.get(&id) {
            Some(v) => *v,
            None => Self::missing(id),
        }
    }

    pub fn total(&self) -> i64 {
        self.lock().total
    }
}


