use arena_scores::Board;
use std::thread;

#[test]
fn concurrent_award_and_opposite_transfers() {
    let b = Board::new();
    b.join(1, 0);
    b.join(2, 0);
    let hs: Vec<_> = (0..8u32).map(|t| {
        let b = b.clone();
        thread::spawn(move || for _ in 0..5000 {
            b.award(1 + t % 2, 1);
            if t % 2 == 0 { b.transfer(1, 2, 1) } else { b.transfer(2, 1, 1) }
            b.transfer(1, 1, 9);
        })
    }).collect();
    for h in hs { h.join().unwrap(); }
    assert_eq!(b.total(), 40000);
    assert_eq!(b.score(1) + b.score(2), 40000);
}

